16	// This file implements R1CS-style constraint definitions: their strict JSON
17	// form, validation against the declared wire layout of a circuit version, a
18	// canonical form used both for persistence and for artifact hashing, and the
19	// modular a·b = c evaluation used by input checking.
20	
21	// maxModulus bounds accepted moduli. The bound keeps every reduced field
22	// element and coefficient inside int32, which makes all constraint
23	// arithmetic exact in int64 (a product of two residues is at most
24	// (p-1)^2 < 2^62).
25	const maxModulus = 2147483647
26	
27	// Term is one wire reference with its coefficient: coeff * value(wire).
28	type Term struct {
29		Wire  int    `json:"wire"`
30		Coeff string `json:"coeff"`
31	}
32	
33	// Constraint is one a·b = c equation modulo the definition's field. Each
34	// slice is a sum of terms; an empty slice is the zero linear combination.
35	type Constraint struct {
36		A []Term `json:"a"`
37		B []Term `json:"b"`
38		C []Term `json:"c"`
39	}
40	
41	// Definition is an importable constraint set. The JSON file carries modulus
42	// as a decimal string and an ordered constraints array.
43	type Definition struct {
44		Modulus     string       `json:"modulus"`
45		Constraints []Constraint `json:"constraints"`
46	}
47	
48	// Artifact is the result of compiling one frozen circuit version. It binds
49	// the version's name, version number, modulus and constraint count to a
50	// stable SHA-256 hash; the same logical circuit always compiles to the same
51	// artifact.
52	type Artifact struct {
53		Name        string
54		Version     int
55		Modulus     int
56		Constraints int
57		Hash        string
58	}
59	
60	// CheckResult is the verdict of testing one input assignment against a
61	// compiled artifact. Satisfied reports whether every constraint holds;
62	// FirstFailure is the 1-based index of the first failing constraint, zero
63	// when the assignment satisfies the circuit.
64	type CheckResult struct {
65		Satisfied    bool
66		Hash         string
67		FirstFailure int
68	}
69	
70	// Witness is one input assignment: values for the declared public and
71	// private wires, in declaration order. Values are arbitrary-length signed
72	// decimal strings interpreted modulo the circuit's field.
73	type Witness struct {
74		Public  []string
75		Private []string
76	}
77	
78	// ---- parsed / canonical in-memory representation -------------------------
79	
80	// parsedTerm is a validated term whose coefficient has been reduced into
81	// [0, modulus).
82	type parsedTerm struct {
83		wire  int
84		value int64 // coefficient mod modulus
85	}
86	
87	// canonicalConstraint groups merged terms by wire.
88	type canonicalConstraint struct {
89		a, b, c []parsedTerm
90	}
91	
92	// canonicalDefinition is a fully validated constraint set in its canonical
93	// form: terms merged per wire, reduced modulo p, zeros removed, wires sorted
94	// ascending within each linear combination.
95	type canonicalDefinition struct {
96		modulus     int64
97		public      int
98		private     int
99		constraints []canonicalConstraint
100	}
101	
102	// maxWire returns the largest wire index referenced anywhere.
103	func (d *canonicalDefinition) maxWire() int {
104		max := 0
105		for _, con := range d.constraints {
106			for _, group := range [][]parsedTerm{con.a, con.b, con.c} {
107				for _, t := range group {
108					if t.wire > max {
109						max = t.wire
110					}
111				}
112			}
113		}
114		return max
115	}
116	
117	// compatibleWith reports whether the definition stays legal when its
118	// version declares the given counts: the constraint count must match and
119	// every referenced wire must still lie inside the declared layout.
120	func (d *canonicalDefinition) compatibleWith(constraints, public, private int) bool {
121		if len(d.constraints) != constraints {
122			return false
123		}
124		return d.maxWire() <= public+private
125	}
126	
127	// toExport renders the canonical form as the public Definition type, with
128	// coefficients reduced to decimal strings in [0, modulus).
129	func (d *canonicalDefinition) toExport() Definition {
130		combo := func(terms []parsedTerm) []Term {
131			r := make([]Term, 0, len(terms))
132			for _, t := range terms {
133				r = append(r, Term{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
134			}
135			return r
136		}
137		cons := make([]Constraint, 0, len(d.constraints))
138		for _, con := range d.constraints {
139			cons = append(cons, Constraint{A: combo(con.a), B: combo(con.b), C: combo(con.c)})
140		}
141		return Definition{Modulus: fmt.Sprintf("%d", d.modulus), Constraints: cons}
142	}
