553	// ---- artifact hashing -----------------------------------------------------
554	
555	// artifactHash computes the stable SHA-256 of a compiled version. It folds
556	// in everything the version's correctness depends on: name, version,
557	// modulus, the public/private split and the ordered, canonical constraints.
558	//
559	// Consequently only semantically equivalent rewrites hash alike: JSON
560	// whitespace, term order, duplicate terms that merge, added/removed zero
561	// terms, and coefficients differing by a multiple of the modulus. Constraint
562	// order, modulus, name, version and the input partition change the hash.
563	func artifactHash(name string, version int, d *canonicalDefinition) string {
564		h := sha256.New()
565		writeLine := func(prefix, value string) {
566			io.WriteString(h, prefix+"="+value+"\n")
567		}
568		writeLine("name", name)
569		writeLine("version", fmt.Sprintf("%d", version))
570		writeLine("modulus", fmt.Sprintf("%d", d.modulus))
571		writeLine("public_inputs", fmt.Sprintf("%d", d.public))
572		writeLine("private_inputs", fmt.Sprintf("%d", d.private))
573		writeLine("constraint_count", fmt.Sprintf("%d", len(d.constraints)))
574		for i, con := range d.constraints {
575			fmt.Fprintf(h, "constraint=%d\n", i)
576			writeCombo(h, "a", con.a)
577			writeCombo(h, "b", con.b)
578			writeCombo(h, "c", con.c)
579		}
580		return hex.EncodeToString(h.Sum(nil))
581	}
582	
583	func writeCombo(h hash.Hash, side string, terms []parsedTerm) {
584		fmt.Fprintf(h, "%s=%d", side, len(terms))
585		for _, t := range terms {
586			fmt.Fprintf(h, " %d:%d", t.wire, t.value)
587		}
588		io.WriteString(h, "\n")
589	}
