591	// ---- canonical JSON for persistence --------------------------------------
592	
593	func (d *canonicalDefinition) toPersist() persistDefinition {
594		out := persistDefinition{
595			Modulus:     fmt.Sprintf("%d", d.modulus),
596			Constraints: make([]persistConstraint, 0, len(d.constraints)),
597		}
598		combo := func(terms []parsedTerm) []persistTerm {
599			tt := make([]persistTerm, 0, len(terms))
600			for _, t := range terms {
601				tt = append(tt, persistTerm{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
602			}
603			return tt
604		}
605		for _, con := range d.constraints {
606			out.Constraints = append(out.Constraints, persistConstraint{
607				A: combo(con.a), B: combo(con.b), C: combo(con.c),
608			})
609		}
610		return out
611	}
612	
613	// definitionFromPersist re-validates a stored definition against its
614	// version's declared input counts and rebuilds its canonical form. It is
615	// used both at load time (integrity check) and before compile/check.
616	func definitionFromPersist(p persistDefinition, public, private int) (*canonicalDefinition, error) {
617		combo := func(tt []persistTerm) []Term {
618			r := make([]Term, 0, len(tt))
619			for _, t := range tt {
620				r = append(r, Term{Wire: t.Wire, Coeff: t.Coeff})
621			}
622			return r
623		}
624		cons := make([]Constraint, 0, len(p.Constraints))
625		for _, c := range p.Constraints {
626			cons = append(cons, Constraint{A: combo(c.A), B: combo(c.B), C: combo(c.C)})
627		}
628		raw, err := json.Marshal(Definition{Modulus: p.Modulus, Constraints: cons})
629		if err != nil {
630			return nil, err
631		}
632		return parseDefinitionJSON(raw, public, private, len(cons))
633	}
