635	// ---- input checking -------------------------------------------------------
636	
637	// parseWitness validates the check input JSON and tags every rejection as an
638	// input format error (ErrInvalidInput), distinct from domain rule failures.
639	func parseWitness(raw []byte, public, private int) (Witness, error) {
640		w, err := parseWitnessDocument(raw, public, private)
641		if err != nil {
642			var se StoreError
643			if errors.As(err, &se) {
644				return Witness{}, StoreError{Kind: ErrInvalidInput.Kind, Detail: se.Detail}
645			}
646			return Witness{}, inputFormatf("%v", err)
647		}
648		return w, nil
649	}
650	
651	// parseWitnessDocument parses and validates a check input document: both
652	// groups must be present as arrays, their lengths must match the
653	// declaration, and every value must be an arbitrarily long signed decimal
654	// string.
655	//
656	// Privacy rule. Diagnostics for the private group never quote a private
657	// value, a character or fragment taken from one, an object key found inside
658	// the private array, or the raw bytes the parser ran into. Private problems
659	// are identified structurally instead — the 1-based private input index, the
660	// group name and the required shape — so a caller can repair the document
661	// without learning its private contents. Public diagnostics keep their full
662	// detail. When a document is too damaged to tell which group a token belongs
663	// to, it is rejected generically as malformed JSON with no source quoted.
664	func parseWitnessDocument(raw []byte, public, private int) (Witness, error) {
665		members, err := splitWitnessObject(raw)
666		if err != nil {
667			return Witness{}, err
668		}
669		publicRaw, havePublic := members["public"]
670		privateRaw, havePrivate := members["private"]
671		if !havePublic {
672			return Witness{}, invalidf("input is missing required field %q: the public group must be an array of decimal strings", "public")
673		}
674		if !havePrivate {
675			return Witness{}, invalidf("input is missing required field %q: the private group must be an array of decimal strings", "private")
676		}
677		pubValues, err := parsePublicArray(publicRaw)
678		if err != nil {
679			return Witness{}, err
680		}
681		privValues, err := parsePrivateArray(privateRaw)
682		if err != nil {
683			return Witness{}, err
684		}
685		return witnessFromArrays(pubValues, privValues, public, private)
686	}
687	
688	// splitWitnessObject walks only the top-level {"public":…,"private":…}
689	// envelope and returns each member's raw value. It exists to attribute a
690	// lexical failure to the right group before the value is decoded, so a
691	// syntax error inside the private value can be reported without quoting the
692	// character the decoder met there.
693	//
694	// Top-level key names are fixed schema names ("public"/"private"), so
695	// quoting an unknown or duplicated top-level field cannot disclose a
696	// private value. A failure while reading a key or the opening/closing brace
697	// is unattributable and reported as plain malformed JSON with no source text.
698	func splitWitnessObject(raw []byte) (map[string]json.RawMessage, error) {
699		trimmed := bytes.TrimSpace(raw)
700		if len(trimmed) == 0 || trimmed[0] != '{' {
701			return nil, invalidf("input must be a JSON object with %q and %q arrays", "public", "private")
702		}
703		dec := json.NewDecoder(bytes.NewReader(trimmed))
704		open, err := dec.Token()
705		if err != nil || open != json.Delim('{') {
706			return nil, invalidf("input is not valid JSON")
707		}
708		members := make(map[string]json.RawMessage)
709		for dec.More() {
710			keyTok, err := dec.Token()
711			if err != nil {
712				return nil, invalidf("input is not valid JSON")
713			}
714			key, ok := keyTok.(string)
715			if !ok {
716				return nil, invalidf("input is not valid JSON")
717			}
718			if key != "public" && key != "private" {
719				return nil, invalidf("input has unknown field %q: only %q and %q are allowed", key, "public", "private")
720			}
721			if _, duplicated := members[key]; duplicated {
722				return nil, invalidf("input contains duplicate field %q", key)
723			}
724			var value json.RawMessage
725			if err := dec.Decode(&value); err != nil {
726				if key == "private" {
727					// Inside the private section: describe the problem, never the
728					// character, offset or fragment the parser encountered.
729					return nil, invalidf("input field %q is not valid JSON: the private group must be an array of decimal strings", key)
730				}
731				return nil, invalidf("input field %q is not valid JSON: %v", key, err)
732			}
733			members[key] = value
734		}
735		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
736			return nil, invalidf("input is not valid JSON")
737		}
738		// Anything after the top-level object (including more JSON tokens) is
739		// trailing data at an unattributable location; report it generically.
740		if _, err := dec.Token(); err != io.EOF {
741			return nil, invalidf("input is not valid JSON: trailing data after the object")
742		}
743		return members, nil
744	}
745	
746	// parsePublicArray decodes the public group with full diagnostics. Public
747	// input is not confidential, so the underlying parser error — including the
748	// offending value — is retained.
749	func parsePublicArray(raw json.RawMessage) ([]string, error) {
750		const which = "public"
751		if string(bytes.TrimSpace(raw)) == "null" {
752			return nil, invalidf("input field %q must be an array of decimal strings, not null", which)
753		}
754		var values []string
755		if err := json.Unmarshal(raw, &values); err != nil {
756			return nil, invalidf("input field %q must be an array of decimal strings: %v", which, err)
757		}
758		return values, nil
759	}
760	
761	// parsePrivateArray decodes the private group without ever quoting its
762	// contents. Each element must be a JSON string; a number, boolean, null,
763	// object or nested array is rejected by its 1-based position alone. An
764	// object element is rejected at its opening brace and never descended into,
765	// so a duplicate key (or any key) inside it cannot be reported.
766	func parsePrivateArray(raw json.RawMessage) ([]string, error) {
767		const which = "private"
768		trimmed := bytes.TrimSpace(raw)
769		if len(trimmed) == 0 || string(trimmed) == "null" || trimmed[0] != '[' {
770			return nil, invalidf("input field %q must be an array of decimal strings", which)
771		}
772		dec := json.NewDecoder(bytes.NewReader(trimmed))
773		dec.UseNumber()
774		if open, err := dec.Token(); err != nil || open != json.Delim('[') {
775			return nil, invalidf("input field %q is not valid JSON: it must be an array of decimal strings", which)
776		}
777		values := []string{}
778		index := 0
779		for dec.More() {
780			index++
781			tok, err := dec.Token()
782			if err != nil {
783				return nil, invalidf("input field %q is not valid JSON: element #%d must be a decimal string", which, index)
784			}
785			switch t := tok.(type) {
786			case string:
787				values = append(values, t)
788			case json.Delim:
789				kind := "array"
790				if t == '{' {
791					kind = "object"
792				}
793				return nil, invalidf("private input #%d must be a decimal string, not an %s", index, kind)
794			case json.Number, float64:
795				return nil, invalidf("private input #%d must be a decimal string, not a number", index)
796			case bool:
797				return nil, invalidf("private input #%d must be a decimal string, not a boolean", index)
798			case nil:
799				return nil, invalidf("private input #%d must be a decimal string, not null", index)
800			}
801		}
802		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
803			return nil, invalidf("input field %q is not valid JSON: it must be an array of decimal strings", which)
804		}
805		return values, nil
806	}
807	
808	// witnessFromArrays applies the single witness grammar and layout rule
809	// shared by both check entry points: each group must contain exactly the
810	// declared number of decimal strings. A nil slice is accepted wherever an
811	// empty one would be (an in-API witness declaring zero inputs); unlike the
812	// JSON entry point nothing here distinguishes "omitted" from "empty".
813	// Private values are never echoed; private problems are identified by index.
814	func witnessFromArrays(pubValues, privValues []string, public, private int) (Witness, error) {
815		if len(pubValues) != public {
816			return Witness{}, invalidf("public input array has %d values but the version requires %d decimal strings",
817				len(pubValues), public)
818		}
819		if len(privValues) != private {
820			return Witness{}, invalidf("private input array has %d values but the version requires %d decimal strings",
821				len(privValues), private)
822		}
823		if err := validateWitnessValues(pubValues, "public", true); err != nil {
824			return Witness{}, err
825		}
826		if err := validateWitnessValues(privValues, "private", false); err != nil {
827			return Witness{}, err
828		}
829		return Witness{Public: pubValues, Private: privValues}, nil
830	}
831	
832	// validateWitnessValues checks that every entry is an arbitrarily long
833	// signed decimal string. Public values may be echoed with the parser's
834	// detailed reason; private values are never quoted, and their failure is
835	// described structurally (see signedDecimalKind) with a 1-based index.
836	func validateWitnessValues(values []string, which string, echo bool) error {
837		for i, v := range values {
838			if _, err := parseBigSignedDecimal(v); err != nil {
839				if echo {
840					return invalidf("%s input #%d value %q is not a decimal integer: %v", which, i+1, v, err)
841				}
842				return invalidf("%s input #%d is not a decimal integer: %s", which, i+1, signedDecimalKind(v))
843			}
844		}
845		return nil
846	}
847	
848	// evaluate checks every constraint against the witness and returns the
849	// 1-based index of the first failure, or 0 when all hold.
850	func (d *canonicalDefinition) evaluate(w Witness) int {
851		p := d.modulus
852		// Wire layout: 0 = 1, then public inputs, then private inputs.
853		values := make([]int64, 1+d.public+d.private)
854		values[0] = 1
855		bigP := big.NewInt(p)
856		for i, s := range w.Public {
857			n, _ := parseBigSignedDecimal(s)
858			n.Mod(n, bigP)
859			values[1+i] = n.Int64()
860		}
861		for i, s := range w.Private {
862			n, _ := parseBigSignedDecimal(s)
863			n.Mod(n, bigP)
864			values[1+d.public+i] = n.Int64()
865		}
866		combo := func(terms []parsedTerm) int64 {
867			var sum int64
868			for _, t := range terms {
869				// sum < p and the product < (p-1)^2 < 2^62, so this add never
870				// overflows int64.
871				sum = modInt64(sum+t.value*values[t.wire], p)
872			}
873			return sum
874		}
875		for i, con := range d.constraints {
876			av := combo(con.a)
877			bv := combo(con.b)
878			cv := combo(con.c)
879			if modInt64(av*bv, p) != cv {
880				return i + 1
881			}
882		}
883		return 0
884	}
