		// committing anything.
		if patch.Constraints == nil && patch.PublicInputs == nil && patch.PrivateInputs == nil && patch.Description == nil {
			result = circuitFromPersist(*existing)
			return false, nil
		}
		result = commitCircuitUpdate(existing, merged.Constraints, merged.PublicInputs, merged.PrivateInputs, merged.Description)
		return true, nil
	})
	return result, err
}

